function cx(...args) {
let out = "";
for (const arg of args) {
if (!arg) continue;
if (typeof arg === "string") out += (out ? " " : "") + arg;
else if (Array.isArray(arg)) {
const next = cx(...arg);
if (next) out += (out ? " " : "") + next;
} else if (typeof arg === "object") {
for (const key in arg) if (arg[key]) out += (out ? " " : "") + key;
}
}
return out;
}

